UPDATE companies SET description='Founded in 1987 in Milwaukee, Wisconsin, Excel Connection Inc. operates a 30,000-square-foot manufacturing facility on South 9th Street with room to expand by an additional 30,000 square feet. The company has served customers nationwide for nearly four decades, building a reputation for custom wire and cable solutions.

The company produces lead wires, wire harnesses, cable assemblies, ribbon cables, coaxial cables, fiber-optic cables, power cables, heavy-gauge cables up to 777 MCM, and electro-mechanical panel assemblies. Its automated equipment handles wire cutting, stripping, crimping, soldering, marking, braiding, loom installation, MIL-spec protective coatings, ultrasonic splicing, epoxy potting, and high-voltage (HIPOT) and pull-force testing up to 1,000 pounds. Value-added services include material kitting, vendor-managed inventory programs, prototyping, and same-day service on select orders.

Excel Connection serves diverse industries, with explicit experience in alternative energy and medical manufacturing. Its customer base ranges from OEMs requiring high-volume simple lead wires to clients needing low-quantity, complex harness assemblies for industrial and commercial applications.

The company emphasizes fast, on-time delivery, quick turnaround times, and engineering support as key differentiators. Its quality system is certified to ISO 9001:2015, and personnel are trained to IPC/WHMA-A-620 standards for both RoHS-compliant and lead-based soldering. Bilingual support in English and Spanish further extends its national and international reach.', certifications=ARRAY['ISO 9001:2015','IPC/WHMA-A-620']::text[], profile='{"capabilities": ["Cable assembly", "Wire harness assembly", "Lead wire assembly", "Electro-mechanical assembly", "Heavy gauge cable processing (up to 777 MCM)", "Wire cutting and stripping (24 gauge to 777 MCM)", "Wire marking (inkjet printing, Brady labels, heat shrink ID)", "Braiding and loom protective coverings", "MIL-spec protective coatings", "Feed-through epoxy/potting", "Ultrasonic splicing and sonic welding", "Panel box and DIN rail assembly", "Coil cord and plug assembly", "Pull force testing and certification (up to 1,000 lbs)", "HIPOT (high voltage) testing", "Circuit testing on assembly boards", "Soldering (RoHS and lead-based per IPC/WHMA-A-620)", "Material and parts kitting", "Vendor-managed stocking programs", "Prototyping services"], "industries": ["Alternative Energy", "Medical Manufacturing"], "materials": [], "equipment": ["Automated wire processing machinery (strips, terminates, solders)", "Induction soldering equipment", "HIPOT testing equipment", "Braiding equipment", "Circuit testing on assembly boards", "Cable cutting and crimping tools (up to 777 MCM)", "15,000 lb. and 6,000 lb. forklifts", "Automated crimp monitoring presses", "Hydraulic crimpers with pre-pull and post-pull testing", "Custom hydraulic equipment for cutting, crimping, pull testing up to 777 MCM", "State-of-the-art automated wire and cable cutting equipment"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Same-day service on select orders", "Vendor-managed inventory programs with automated scheduling", "Automated wire processing up to 777 MCM with UL pull-test certification to 1,000 lbs", "ISO 9001:2015 and IPC/WHMA-A-620 certified quality system", "Bilingual (English/Spanish) customer support"], "facts_used": ["Founded 1987 -> db founded_year and /about-us ''Year Established 1987''", "Headquarters Milwaukee, WI -> db hq_city/hq_state_label and /about-us address", "Facility size 30,000 sq ft with expansion potential -> /about-us", "Product range (lead wires, harnesses, cable assemblies, etc.) -> /about-us", "Heavy gauge cable up to 777 MCM -> /capabilities and db description", "UL pull test up to 1,000 lbs -> db description and /capabilities", "Automated wire processing capabilities -> /capabilities", "Wire marking (inkjet, Brady labels, heat shrink) -> /capabilities", "Braiding/loom, MIL-spec coatings, ultrasonic splicing, epoxy potting -> /capabilities", "Panel box/DIN rail assembly, coil cords, plugs -> /capabilities", "Pull force testing, HIPOT testing, circuit testing -> /capabilities", "Soldering per IPC/WHMA-A-620 (RoHS and lead-based) -> /capabilities", "Material kitting, vendor-managed stocking, prototyping -> /capabilities and db capabilities", "Same-day service -> / (home page) ''Offering same-day service''", "ISO 9001:2015 certified -> / and /about-us", "IPC-620 certified personnel -> / and /about-us", "Languages English and Spanish -> /about-us", "Industries: Alternative Energy, Medical Manufacturer -> db industries_served", "Equipment list -> /capabilities", "LinkedIn URL -> db linkedin_url"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Based in Milwaukee, WI, Excel Connection Inc is a respected manufacturer of lead wires, wire harnesses, cable assemblies, ribbon cables, coaxial cables, fiber optics, power cables, heavy gauge cables and electro-mechanical panels.", "founded_year": "1987", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": ["English", "Spanish"], "social_links": ["https://www.linke